-- SECRETS-CENSUS-1 (2026-11-05, charter pillar security; agent_issues 1000698, ROADMAP-1 QNFO.INFRA #2). The item reads as merged (PR 5170) and its closing probe counted failed
-- migration_runs (188 rows), which measures neither the secrets nor the store. Measured today from the Cloudflare API (39 workers, reads only, no secret value read): 112
-- secret_text bindings, 0 secrets_store_secret bindings; the default Secrets Store (8ef28060302e4311b064ba3529493e8b) holds 30 named secrets. qnfo-infra/wrangler.toml has
-- declared [[secrets_store_secrets]] binding CF_TOKEN_STORE (secret CF_API_TOKEN) since 2026-11-01 (PR 5746) and the live worker has no such binding: the declared-binding
-- installer of the canonical deploy (qnfo-ops installDeclaredBindings) parses d1, r2, kv, ai, services and analytics_engine_datasets and has no case for secrets_store_secrets,
-- so the declaration is inert. qnfo-infra 1.12.2 records secrets_census (secret_text and store bindings per worker) in its snapshot; the probe below reads it.
-- The unblocker is a one-case change in qnfo-ops, filed with a doer and a closing probe as DECLARED-SECRETS-STORE-1 (the successor stays open on rollback; close it with evidence).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261105_secrets_census b WHERE b.class = remediation_contracts.class), action = (SELECT b.action FROM bak_20261105_secrets_census b WHERE b.class = remediation_contracts.class), attempts = 0, last_verdict = NULL, next_due_at = datetime('now') WHERE class = 'issue-1000698' AND EXISTS (SELECT 1 FROM bak_20261105_secrets_census b WHERE b.class = 'issue-1000698'); UPDATE agent_issues SET description = substr(description, 1, instr(description, char(10) || 'SECRETS-CENSUS-1 2026-11-05') - 1) WHERE id = 1000698 AND instr(description, char(10) || 'SECRETS-CENSUS-1 2026-11-05') > 0

CREATE TABLE IF NOT EXISTS bak_20261105_secrets_census AS
SELECT class, issue_id, action, verify_probe, verify_transport, status, last_verdict FROM remediation_contracts WHERE class = 'issue-1000698';

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'DECLARED-SECRETS-STORE-1: the canonical deploy ignores [[secrets_store_secrets]], so the Secrets Store binding qnfo-infra declared on 2026-11-01 never reached Cloudflare',
 'Charter pillar: security. Serves ROADMAP-1 QNFO.INFRA #2 (agent_issues 1000698). Measured 2026-11-05 from the Cloudflare API over 39 workers: 112 secret_text bindings and 0 secrets_store_secret bindings. qnfo-infra/wrangler.toml declares [[secrets_store_secrets]] binding CF_TOKEN_STORE (store 8ef28060302e4311b064ba3529493e8b, secret CF_API_TOKEN, which the store lists among its 30 names) since 2026-11-01 (PR 5746); the live qnfo-infra settings carry CF_ACCOUNT, CF_TOKEN and INFRA_TOKEN as secret_text and no store binding. Cause: qnfo-ops installDeclaredBindings, the declared-binding installer of the canonical deploy, parses d1_databases, r2_buckets, kv_namespaces, ai, services and analytics_engine_datasets and has no case for secrets_store_secrets, so the declaration is inert (the same inert-config class as the placement and limits tables fixed earlier). Lever: add the case, decl.push({ type: "secrets_store_secret", name: nm, store_id: k.store_id, secret_name: k.secret_name }) for a section named secrets_store_secrets with those keys, and a suite case: a wrangler.toml with the table yields exactly one binding of that type. Activation note, decided here so nobody waits on it: the first qnfo-infra deploy after the case lands binds CF_TOKEN_STORE and infraSecret prefers the store value over CF_TOKEN; a rejected store value fails loudly (qnfo-infra/secrets-store.test.mjs pins that there is no silent bypass), the infra snapshot and the cost ledger tick then record the error, and the revert is deleting the table from qnfo-infra/wrangler.toml and redeploying. No secret value is read, written or logged by this change; the secret lock applies to any later removal of a secret_text value, not to this binding. Done: qnfo-ops/worker.js parses the table (code-probe below), and after the qnfo-infra deploy its live settings carry CF_TOKEN_STORE: the qnfo-infra snapshot reads secrets_census.store_bindings >= 1 (qnfo-infra 1.12.2) and /health is ok. Control plane: left to the stale-PR lane to merge.
code-probe: {"paths": ["qnfo-ops/worker.js"], "contains": "secrets_store_secret"}
code-task: repo=qnfo-workers path=qnfo-ops/worker.js
code-anchor: else if (s.name === "ai") decl.push({ type: "ai", name: nm });',
 'session', 'reliability', 'high', 'open', CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE title LIKE 'DECLARED-SECRETS-STORE-1:%' AND status = 'open');

UPDATE remediation_contracts
SET verify_probe = 'WITH c AS (SELECT json_extract(data, ''$.secrets_census.store_bindings'') AS s, json_extract(data, ''$.secrets_census.secret_text'') AS t FROM infra_state WHERE id = ''snapshot'' ORDER BY ts DESC LIMIT 1) SELECT ''secrets store bindings cover the per-worker secret_text bindings'' AS expected, CASE WHEN s IS NULL THEN ''the snapshot has no secrets_census yet (qnfo-infra 1.12.2 not live)'' WHEN t = 0 OR s >= t THEN ''secrets store bindings cover the per-worker secret_text bindings'' ELSE s || '' store bindings against '' || t || '' secret_text bindings'' END AS observed FROM c',
    action = 'SECRETS-CENSUS-1: passes when the live settings of the workers carry at least as many secrets_store_secret bindings as secret_text bindings (qnfo-infra snapshot secrets_census). Replaces the probe that counted failed migration runs. The binding installer gap is DECLARED-SECRETS-STORE-1.',
    attempts = 0, last_verdict = NULL, next_due_at = datetime('now')
WHERE class = 'issue-1000698' AND issue_id = 1000698
  AND verify_probe LIKE '%migration_runs%';

UPDATE agent_issues
SET description = description || char(10) || 'SECRETS-CENSUS-1 2026-11-05: measured from the Cloudflare API over 39 workers, 112 secret_text bindings and 0 secrets_store_secret bindings; the Secrets Store holds 30 named secrets. The merged change (PR 5170) taught qnfo-infra to read a store binding and PR 5746 declared CF_TOKEN_STORE in its wrangler.toml, but the canonical deploy never installs [[secrets_store_secrets]] (qnfo-ops installDeclaredBindings has no case), so the store has no consumer. The unblocker is filed as ' || coalesce((SELECT 'agent_issues ' || id FROM agent_issues WHERE title LIKE 'DECLARED-SECRETS-STORE-1:%' AND status = 'open' ORDER BY id DESC LIMIT 1), 'DECLARED-SECRETS-STORE-1') || ' (code-task on qnfo-ops/worker.js). After it, the remaining 112 bindings move one worker at a time: declare the store binding, deploy, verify the worker, then remove its secret_text under the secret lock. This ticket closes on its own probe when store bindings cover the secret_text bindings.'
WHERE id = 1000698 AND status = 'open' AND instr(description, 'SECRETS-CENSUS-1 2026-11-05') = 0;
